(7148713, 1096119, 97225, '<td valign="top">Wonderful image and a great fit to the challenge. One of my ribbon choices.</td>', 'Wonderful image and a great fit to the challenge. One of my ribbon choices.', '2013-12-29 07:13:49.000000', NULL, 1),
