(7148954, 1096119, 150277, '<td valign="top">I love how the sun seems to burst out.</td>', 'I love how the sun seems to burst out.', '2013-12-29 16:51:49.000000', NULL, 1),
(7148955, 1096211, 150277, '<td valign="top">Very powerful sky.  Striking shot.</td>', 'Very powerful sky.  Striking shot.', '2013-12-29 16:52:34.000000', NULL, 1),
(7148956, 1096190, 150277, '<td valign="top">Brilliant photo. Just gorgeous and indeed scary.</td>', 'Brilliant photo. Just gorgeous and indeed scary.', '2013-12-29 16:53:22.000000', NULL, 1),
(7148957, 1096101, 150277, '<td valign="top">The shortest day seems to have made your subject a bit sad.  Me too.  And I love the photo.</td>', 'The shortest day seems to have made your subject a bit sad.  Me too.  And I love the photo.', '2013-12-29 16:55:13.000000', NULL, 1),
