(7149142, 1096190, 66641, '<td valign="top">What an amazing shot, this is stunning.  It reminds me of the drive to/from Haleakala crater on Maui.  Very nice. :) (haven''t voted yet)</td>', 'What an amazing shot, this is stunning.  It reminds me of the drive to/from Haleakala crater on Maui.  Very nice. :) (haven''t voted yet)', '2013-12-29 22:29:32.000000', NULL, 1),
(7149184, 1096173, 96751, '<td valign="top">What a delightful artifact!</td>', 'What a delightful artifact!', '2013-12-29 23:17:05.000000', NULL, 1),
(7149185, 1096297, 96751, '<td valign="top">Ha! Or waiting for the doors to open for some monster sale :)</td>', 'Ha! Or waiting for the doors to open for some monster sale :)', '2013-12-29 23:17:36.000000', NULL, 1),
(7149186, 1096306, 96751, '<td valign="top">Lovely portrait, though it is hard to associate this image with the Solstice</td>', 'Lovely portrait, though it is hard to associate this image with the Solstice', '2013-12-29 23:18:27.000000', NULL, 1),
(7149187, 1096191, 96751, '<td valign="top">I like the clinical yet artistic approach.</td>', 'I like the clinical yet artistic approach.', '2013-12-29 23:18:48.000000', NULL, 1),
(7149190, 1096119, 96751, '<td valign="top">This reminds me of a place I visited in India, where they had giant astronomical instruments that looked very much like this.  A wonderful capture, with very interesting pp''g.</td>', 'This reminds me of a place I visited in India, where they had giant astronomical instruments that looked very much like this.  A wonderful capture, with very interesting pp''g.', '2013-12-29 23:19:52.000000', NULL, 1),
(7149192, 1096178, 96751, '<td valign="top">Lyn, are you taking pictures out your window again...?</td>', 'Lyn, are you taking pictures out your window again...?', '2013-12-29 23:20:17.000000', NULL, 1),
(7149193, 1095783, 96751, '<td valign="top">It seems the world is sliding off to the left</td>', 'It seems the world is sliding off to the left', '2013-12-29 23:20:38.000000', NULL, 1),
(7149194, 1096211, 96751, '<td valign="top">I''m not a fan of the pp''g, although I think this has potential</td>', 'I''m not a fan of the pp''g, although I think this has potential', '2013-12-29 23:21:25.000000', NULL, 1),
(7149195, 1095823, 96751, '<td valign="top">Um, unless you''re in the southern hemisphere (which is possible), Winter Solstice is actually the <i>shortest</i> day...</td>', 'Um, unless you''re in the southern hemisphere (which is possible), Winter Solstice is actually the shortest day...', '2013-12-29 23:22:07.000000', NULL, 1),
(7149198, 1096103, 96751, '<td valign="top">Beautiful. I imagine it is very quiet, and the smell is crisp with a hint of burning wood. But I don''t see this as a "solstice" image</td>', 'Beautiful. I imagine it is very quiet, and the smell is crisp with a hint of burning wood. But I don''t see this as a "solstice" image', '2013-12-29 23:23:21.000000', NULL, 1),
(7149199, 1096249, 96751, '<td valign="top">Very handsome image</td>', 'Very handsome image', '2013-12-29 23:23:35.000000', NULL, 1),
(7149201, 1096294, 96751, '<td valign="top">Woolworth building?  Great reflection</td>', 'Woolworth building?  Great reflection', '2013-12-29 23:24:05.000000', NULL, 1),
(7149204, 1095954, 96751, '<td valign="top">VERY clever. I''m trying to figure out what you used to create the stones, as this is clearly not the real deal. Just marvelous. So far, my favorite entry. The Druids had it right.</td>', 'VERY clever. I''m trying to figure out what you used to create the stones, as this is clearly not the real deal. Just marvelous. So far, my favorite entry. The Druids had it right.', '2013-12-29 23:25:09.000000', NULL, 1),
(7149205, 1096030, 96751, '<td valign="top">Beautiful image. The sun, low in the sky, could easily be the solstice sun. The setting is sublime</td>', 'Beautiful image. The sun, low in the sky, could easily be the solstice sun. The setting is sublime', '2013-12-29 23:25:49.000000', NULL, 1),
(7149214, 1096101, 96751, '<td valign="top">Magnificent portrait.</td>', 'Magnificent portrait.', '2013-12-29 23:37:19.000000', NULL, 1),
